from dataclasses import dataclass, field
import json
import re
import sys
from typing import Optional

GUARDED = re.compile(r"\$\{[A-Za-z_]\w*:\?")
BRACED = re.compile(r"\$\{([A-Za-z_]\w*)\}")
NAME = re.compile(r"[A-Za-z_]\w*")
SPECIAL = re.compile(r"[0-9@*#?$!-]")
ASSIGNMENT = re.compile(r"([A-Za-z_]\w*)(\+?)=")
# Słowa przed nazwą polecenia: słowa kluczowe Basha i polecenia, które uruchamiają swoje argumenty.
PREFIXES = frozenset(
    {"!", "{", "}", "do", "done", "then", "else", "elif", "fi", "if", "while", "until", "time", "sudo", "command",
     "builtin", "exec", "nohup"}
)
# Nagłówek pętli, ``case`` albo funkcji nie uruchamia polecenia, ale czyni całość złożoną.
HEADERS = frozenset({"for", "select", "case", "function"})

WHY = (
    "Claude Code w trybie bypass zatrzymuje rm w poleceniu złożonym, którego nie umie rozwiązać statycznie, na zgodzie, "
