@dataclass
class Word:
    """Słowo polecenia: tekst bez cudzysłowów i to, od czego zależy jego wartość."""

    text: str = ""
    variables: set[str] = field(default_factory=set)
    opaque: bool = False
    globbed: bool = False
    resolved: bool = True

    @property
    def expanded(self) -> bool:
        return bool(self.variables) or self.opaque


@dataclass
class Shell:
    """Proste polecenia Basha z tekstu i to, czego nie da się w nim rozwiązać statycznie."""

    commands: list[list[Word]] = field(default_factory=list)
    compound: bool = False
    ambiguous_close: bool = False


@dataclass(frozen=True)
class Refusal:
    reason: str

    @property
    def message(self) -> str:
        return f"Odmowa: {self.reason} {WHY} {FIX}"


class _Reader:
    """Czyta tekst polecenia znak po znaku: cudzysłowy, rozwinięcia ``$``, podstawienia, przekierowania i heredoki."""

    def __init__(self, text: str) -> None:
        self.text = text
        self.at = 0
        self.shell = Shell()
        self.heredocs: list[tuple[str, bool]] = []
        # Zmienne, którym polecenie wcześniej nadało dosłowną wartość (``D=/abs; rm -rf $D/x``).
        self.literal: set[str] = set()

    def peek(self, offset: int = 0) -> str:
        return self.text[self.at + offset : self.at + offset + 1]

    def commands(self, stop: str) -> None:
        """Polecenia do ``stop`` (``)`` po ``$(``, `` ` ``) poza cudzysłowem albo do końca tekstu."""

        words: list[Word] = []
        subshells = 0
        redirected = False
        while self.at < len(self.text):
            char = self.text[self.at]
            if char == stop and not subshells:
                self.at += 1
                break
            if char in " \t" or self.text.startswith("\\\n", self.at):
                self.at += 1 if char != "\\" else 2
                continue
            if char == "#":
                newline = self.text.find("\n", self.at)
                self.at = len(self.text) if newline < 0 else newline
                continue
            if char in "<>" or (char == "&" and self.peek(1) == ">"):
                if self.peek(1) == "(":
                    self.at += 2
                    self.substitution(")")
                else:
                    redirected = self.redirection()
                continue
            if char not in "\n;&|()":
                word = self.word()
                if not redirected and not (word.text.isdigit() and self.peek() in ("<", ">")):
                    words.append(word)
                redirected = False
                continue
            self.end(words)
            words, redirected = [], False
            self.at += 1
            if char == "\n":
                self.skip_heredocs()
            elif char == "(" and self.peek() == "(":
                self.at = self.arithmetic(self.at + 1)
            elif char == "(":
                self.shell.compound = True
                subshells += 1
            elif char == ")" and subshells:
                subshells -= 1
                if not subshells and stop == ")" and self.peek() == ")":
                    self.shell.ambiguous_close = True
        self.end(words)

    def end(self, words: list[Word]) -> None:
        start = 0
        assigned: list[tuple[str, Word]] = []
        while start < len(words):
            assignment = ASSIGNMENT.match(words[start].text)
            if assignment and not assignment.group(2):
                assigned.append((assignment.group(1), words[start]))
            elif assignment:
                self.literal.discard(assignment.group(1))
            elif words[start].text not in PREFIXES:
                break
            start += 1
        for word in words:
            word.resolved = not (word.opaque or word.globbed) and word.variables <= self.literal
        if start == len(words):
            for name, value in assigned:
                (self.literal.add if value.resolved else self.literal.discard)(name)
            return
        self.literal.difference_update(name for name, _ in assigned)
        command = words[start].text
        if command in HEADERS:
            self.shell.compound = True
            if command in ("for", "select") and start + 1 < len(words):
                self.literal.discard(words[start + 1].text)
            return
        if command == "read":
            self.literal.difference_update(word.text for word in words[start + 1 :])
        self.shell.commands.append(words[start:])

    def redirection(self) -> bool:
        """Operator przekierowania; ``True``, gdy następne słowo to jego cel, a nie argument polecenia."""

        if self.text.startswith("<<<", self.at):
            self.at += 3
            return False
        if self.text.startswith("<<", self.at):
            self.at += 2
            strip = self.peek() == "-"
            self.at += strip
            while self.peek() in (" ", "\t"):
                self.at += 1
            self.heredocs.append((self.word().text, strip))
            return False
        while self.peek() in ("<", ">", "&", "|"):
            self.at += 1
        return True

    def skip_heredocs(self) -> None:
        for delimiter, strip in self.heredocs:
            while self.at < len(self.text):
                newline = self.text.find("\n", self.at)
                end = len(self.text) if newline < 0 else newline
                line = self.text[self.at : end]
                self.at = end + 1
                if (line.lstrip("\t") if strip else line) == delimiter:
                    break
        self.heredocs = []

    def word(self) -> Word:
        word = Word()
        parts: list[str] = []
        while self.at < len(self.text):
            char = self.text[self.at]
            if char in " \t\n;&|()<>":
                break
            if char == "'":
                close = self.text.find("'", self.at + 1)
                end = len(self.text) if close < 0 else close
                parts.append(self.text[self.at + 1 : end])
                self.at = end + 1
            elif char == '"':
                self.at += 1
                self.characters(word, parts, '"')
            else:
                self.characters(word, parts, "")
        word.text = "".join(parts)
        return word

    def characters(self, word: Word, parts: list[str], quote: str) -> None:
        """Znaki słowa do końca cudzysłowu ``quote`` albo, bez niego, do pierwszego cudzysłowu lub końca słowa."""

        while self.at < len(self.text):
            char = self.text[self.at]
            if char == quote:
                self.at += 1
                return
            if not quote and char in " \t\n;&|()<>'\"":
                return
            start = self.at
            if char == "\\":
                self.at += 2
                parts.append(self.text[start + 1 : self.at])
                continue
            if char in "$`":
                self.expansion(word)
            else:
                word.globbed = word.globbed or char in "*?["
                self.at += 1
            parts.append(self.text[start : self.at])

    def expansion(self, word: Word) -> None:
        """Rozwinięcie od ``$`` albo `` ` ``: zmienna trafia do ``variables``, a reszta oprócz ``${VAR:?}`` czyni słowo nieprzejrzystym."""

        if self.text[self.at] == "`":
            self.at += 1
            self.substitution("`")
            word.opaque = True
        elif self.text.startswith("$((", self.at):
            self.at = self.arithmetic(self.at + 3)
            word.opaque = True
        elif self.text.startswith("$(", self.at):
            self.at += 2
            self.substitution(")")
            word.opaque = True
        elif self.text.startswith("${", self.at):
            depth, index = 0, self.at + 1
            while index < len(self.text):
                depth += {"{": 1, "}": -1}.get(self.text[index], 0)
                index += 1
                if not depth:
                    break
            braced = BRACED.fullmatch(self.text, self.at, index)
            if braced:
                word.variables.add(braced.group(1))
            elif not GUARDED.match(self.text, self.at):
                word.opaque = True
            self.at = index
        elif NAME.match(self.text, self.at + 1):
            name = NAME.match(self.text, self.at + 1)
            word.variables.add(name.group())
            self.at = name.end()
        else:
            special = SPECIAL.match(self.text, self.at + 1)
            word.opaque = word.opaque or special is not None
            self.at += 1 if special is None else 2

    def substitution(self, stop: str) -> None:
        self.shell.compound = True
        self.commands(stop)

    def arithmetic(self, start: int) -> int:
        """Indeks za ``))`` arytmetyki, której ``((`` kończy się przed ``start``."""

        depth, index = 2, start
        while index < len(self.text) and depth:
            depth += {"(": 1, ")": -1}.get(self.text[index], 0)
            index += 1
        return index


def read(command: str) -> Shell:
    reader = _Reader(command)
    reader.commands("")
    return reader.shell


def judge(command: str) -> Optional[Refusal]:
    try:
        shell = read(command)
    except RecursionError:
        return None
    removals = [words for words in shell.commands if words[0].text.rsplit("/", 1)[-1] == "rm"]
    if not removals or not (shell.compound or len(shell.commands) > 1):
        return None
    for words in removals:
        arguments = words[1:]
        end = next((index for index, word in enumerate(arguments) if word.text == "--"), len(arguments))
        for target in [word for word in arguments[:end] if not word.text.startswith("-")] + arguments[end + 1 :]:
            if not target.resolved:
                return Refusal(f"cel rm {target.text} zależy od wartości z chwili uruchomienia (zmienna, $(…) albo glob).")
    for words in shell.commands:
        if words[0].expanded:
            return Refusal(f"polecenie {words[0].text} bierze nazwę ze zmiennej, więc nie wiadomo, co uruchomi obok rm.")
    if shell.ambiguous_close:
        return Refusal("\"))\" zamyka podpowłokę i $(…) naraz, więc parser Claude Code nie widzi, gdzie stoi rm.")
    return None


def main() -> int:
    try:
        command = json.load(sys.stdin)["tool_input"]["command"]
    except (ValueError, KeyError, TypeError, IndexError):
        return 0
    if not isinstance(command, str):
        return 0
    refusal = judge(command)
    if refusal is None:
        return 0
    print(refusal.message, file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main())
